"use client";

import { useEffect } from "react";

export default function TccHome() {
  useEffect(() => {
    const site = document.getElementById("tcc-site");
    if (!site || site.dataset.initialized === "1") return;
    site.dataset.initialized = "1";
    const header = site.querySelector("#tcc-header");
    const progress = site.querySelector("#tcc-progress");
    const toggle = site.querySelector(".tcc-toggle");
    const menu = site.querySelector("#tcc-menu");
    const photo = site.querySelector(".tcc-photo-image");
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)");
    const closeMenu = () => {
      menu.classList.remove("tcc-menu-open");
      toggle.setAttribute("aria-expanded", "false");
      toggle.setAttribute("aria-label", "Open navigation menu");
    };
    const onToggle = () => {
      const open = menu.classList.toggle("tcc-menu-open");
      toggle.setAttribute("aria-expanded", String(open));
      toggle.setAttribute("aria-label", open ? "Close navigation menu" : "Open navigation menu");
    };
    const onKey = (e) => { if (e.key === "Escape") closeMenu(); };
    const onDocClick = (e) => { if (!header.contains(e.target)) closeMenu(); };
    toggle.addEventListener("click", onToggle);
    site.querySelectorAll(".tcc-menu a").forEach((a) => a.addEventListener("click", closeMenu));
    document.addEventListener("keydown", onKey);
    document.addEventListener("click", onDocClick);
    const anchorHandlers = [];
    site.querySelectorAll('a[href^="#"]').forEach((a) => {
      const handler = (e) => {
        const target = document.getElementById(a.getAttribute("href").slice(1));
        if (!target) return;
        e.preventDefault();
        const y = window.scrollY + target.getBoundingClientRect().top - header.offsetHeight + 2;
        window.scrollTo({ top: y, behavior: reduced.matches ? "auto" : "smooth" });
      };
      anchorHandlers.push([a, handler]);
      a.addEventListener("click", handler);
    });
    const scrollUpdate = () => {
      header.classList.toggle("tcc-is-scrolled", window.scrollY > 20);
      const height = document.documentElement.scrollHeight - window.innerHeight;
      progress.style.width = (height > 0 ? Math.max(0, Math.min(100, (window.scrollY / height) * 100)) : 0) + "%";
      if (photo) {
        const rect = photo.getBoundingClientRect();
        const inView = rect.bottom > 0 && rect.top < window.innerHeight;
        const canMove = window.innerWidth > 760 && !reduced.matches;
        if (inView && canMove) {
          let delta = (window.innerHeight / 2 - (rect.top + rect.height / 2)) * 0.13;
          delta = Math.max(-36, Math.min(36, delta));
          photo.style.setProperty("--tcc-parallax-y", delta + "px");
        } else {
          photo.style.setProperty("--tcc-parallax-y", "0px");
        }
      }
    };
    let queued = false;
    const onScroll = () => {
      if (!queued) {
        queued = true;
        requestAnimationFrame(() => { scrollUpdate(); queued = false; });
      }
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", scrollUpdate, { passive: true });
    scrollUpdate();
    const reveals = site.querySelectorAll(".tcc-reveal");
    let observer = null;
    if ("IntersectionObserver" in window && !reduced.matches) {
      observer = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) { entry.target.classList.add("tcc-visible"); observer.unobserve(entry.target); }
        });
      }, { threshold: 0.07, rootMargin: "0px 0px -30px 0px" });
      reveals.forEach((el) => observer.observe(el));
      site.classList.add("tcc-js");
    }
    const yearEl = site.querySelector("#tcc-year");
    if (yearEl) yearEl.textContent = new Date().getFullYear();
    return () => {
      toggle.removeEventListener("click", onToggle);
      document.removeEventListener("keydown", onKey);
      document.removeEventListener("click", onDocClick);
      anchorHandlers.forEach(([a, h]) => a.removeEventListener("click", h));
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", scrollUpdate);
      if (observer) observer.disconnect();
    };
  }, []);

  return (
<div id="tcc-site">
  <header className="tcc-header" id="tcc-header">
    <nav className="tcc-nav tcc-container" aria-label="Main navigation">
      <a className="tcc-brand" href="/" aria-label="Truth and Conciliation Commission — Home"><img src="data:image/webp;base64," alt="Truth and Conciliation logo" width="330" height="181" /></a>
      <button className="tcc-toggle" type="button" aria-label="Open navigation menu" aria-expanded="false" aria-controls="tcc-menu"><span></span><span></span><span></span></button>
      <div className="tcc-menu" id="tcc-menu">
        <a href="/" aria-current="page">Home</a><a href="/about">About</a><a href="/contact">Contact</a>
      </div>
    </nav><div className="tcc-progress" id="tcc-progress" aria-hidden="true"></div>
  </header>
  <main>
    <section className="tcc-hero" id="home" aria-labelledby="tcc-home-title">
      <div className="tcc-container tcc-hero-grid">
        <div>
          <p className="tcc-eyebrow">The Truth &amp; Conciliation Commission</p>
          <h1 id="tcc-home-title">Truth-telling is the beginning.<br /><em>Transformational change</em> is the work.</h1>
          <p className="tcc-hero-desc">Confronting institutional and interpersonal racism through education, storytelling, and transformative action—toward a more equitable, inclusive, and just society.</p>
          <div className="tcc-hero-actions"><a className="tcc-btn tcc-btn-gold" href="#our-work">Explore Our Work</a><a className="tcc-btn tcc-btn-ghost" href="/about">About the Commission</a></div>
          <p className="tcc-hero-fact">Established amid the racial reckoning of 2020</p>
        </div>
        <div className="tcc-photo-frame tcc-reveal">
          <div className="tcc-photo"><div className="tcc-photo-image" role="img" aria-label="Community members engaged in group conversation"></div><div className="tcc-photo-caption">Creating space for truth, dialogue, and change.</div></div><span className="tcc-photo-accent" aria-hidden="true"></span>
        </div>
      </div>
    </section>
    <section className="tcc-mission" id="mission" aria-labelledby="tcc-mission-title">
      <div className="tcc-container tcc-mission-grid">
        <div className="tcc-reveal"><p className="tcc-eyebrow">Who We Are</p><h2 className="tcc-h2" id="tcc-mission-title">A commission rooted in truth. Committed to change.</h2></div>
        <div className="tcc-mission-copy tcc-reveal"><p className="tcc-lead">Born amid the racial reckoning of 2020, the Truth and Conciliation Commission exists to confront the myths, structures, policies, and practices that perpetuate racism.</p><p className="tcc-lead">We seek to identify, examine, and dismantle racism—and help communities and institutions advance more equitable, inclusive, and just ways of living and working together.</p><a className="tcc-text-link" href="/about">Learn About the Commission <span aria-hidden="true">→</span></a></div>
      </div>
    </section>
    <section className="tcc-pillars" id="our-work" aria-labelledby="tcc-pillars-title">
      <div className="tcc-container"><div className="tcc-center tcc-reveal"><p className="tcc-eyebrow">Our Work</p><h2 className="tcc-h2" id="tcc-pillars-title">Three pillars. One commitment.</h2><p className="tcc-lead">Our approach brings learning, lived experience, and action together to make lasting change possible.</p></div>
        <div className="tcc-cards">
          <article className="tcc-card tcc-reveal"><span className="tcc-card-number">01</span><div className="tcc-icon" aria-hidden="true"><svg viewBox="0 0 32 32"><path d="M16 26c-3.2-2-8.3-3-12-2V7c4-.9 9.1 0 12 2.5C18.9 7 24 6.1 28 7v17c-3.7-1-8.8 0-12 2Z"/><path d="M16 9.5V26M8 12c2.1-.2 4 .3 5.1 1.1M20 13.1c1.4-.9 3.2-1.2 5-.9"/></svg></div><h3>Education</h3><p>Resources, facilitated dialogues, workshops, seminars, and convenings that deepen understanding of the history and ongoing effects of racism and oppression.</p></article>
          <article className="tcc-card tcc-reveal"><span className="tcc-card-number">02</span><div className="tcc-icon" aria-hidden="true"><svg viewBox="0 0 32 32"><path d="M5 6h22v15H14l-6 5v-5H5Z"/><path d="M10 12h12M10 16h8"/></svg></div><h3>Testimonials &amp; Storytelling</h3><p>Honoring and gathering personal and communal narratives that illuminate lived experiences and support truth-telling, healing, and restorative justice.</p></article>
          <article className="tcc-card tcc-reveal"><span className="tcc-card-number">03</span><div className="tcc-icon" aria-hidden="true"><svg viewBox="0 0 32 32"><path d="M16 28V15M16 22c-6 0-10-4-10-11 7 0 10 5 10 11ZM16 18c0-7 4-12 11-12 0 7-4 12-11 12Z"/><path d="M9 29h14"/></svg></div><h3>Transformational Change</h3><p>Working with individuals, organizations, and institutions to advance restorative practices, equitable policies, and meaningful, sustained change.</p></article>
        </div>
      </div>
    </section>
    <section className="tcc-statement" aria-labelledby="tcc-statement-title"><div className="tcc-container tcc-statement-inner tcc-reveal"><p className="tcc-eyebrow">Our conviction</p><h2 id="tcc-statement-title">Truth opens the conversation.<br /><span>Change carries it forward.</span></h2></div></section>
    <section className="tcc-leadership" id="leadership" aria-labelledby="tcc-leadership-title"><div className="tcc-container"><div className="tcc-center tcc-reveal"><p className="tcc-eyebrow">Leadership</p><h2 className="tcc-h2" id="tcc-leadership-title">Grounded in scholarship, ministry, and community.</h2><p className="tcc-lead">Meet the voices and experiences informing the Commission's commitment to justice.</p></div>
      <div className="tcc-leaders">
        <article className="tcc-leader tcc-reveal"><small>Founder &amp; Director</small><h3>Rev. Dr. Stephany Rose Spaulding</h3><p>Interdisciplinary scholar and social justice activist committed to transformative ministry and community building.</p></article>
        <article className="tcc-leader tcc-reveal"><small>Public Service &amp; Advocacy</small><h3>Cori Bush-Merritts</h3><p>Former U.S. Representative, nurse, pastor, and community organizer with a background in public service and racial justice advocacy.</p></article>
      </div>
      <div className="tcc-leadership-action"><a className="tcc-btn tcc-btn-dark" href="/about">Read the Leadership Biographies</a></div>
    </div></section>
    <section className="tcc-cta" aria-labelledby="tcc-cta-title"><div className="tcc-container tcc-cta-grid"><div className="tcc-reveal"><h2 id="tcc-cta-title">The work of change begins with conversation.</h2><p>Connect with the Commission to explore dialogue, learning, and opportunities for collaboration.</p></div><a className="tcc-btn tcc-btn-gold" href="/contact">Contact the Commission</a></div></section>
  </main>
  <footer className="tcc-footer"><div className="tcc-container"><div className="tcc-footer-top"><div><a href="/" aria-label="Return to homepage"><img src="data:image/webp;base64," alt="Truth and Conciliation Commission" loading="lazy" width="330" height="181" /></a><p className="tcc-footer-note">Education. Storytelling. Transformational Change.</p></div><nav className="tcc-footer-links" aria-label="Footer navigation"><a href="/">Home</a><a href="/about">About</a><a href="/contact">Contact</a></nav></div><div className="tcc-footer-bottom"><span>© <span id="tcc-year">2026</span> Truth and Conciliation Commission. All rights reserved.</span><div className="tcc-policy-links"><a href="/privacy">Privacy Policy</a><a href="/terms">Terms of Service</a></div></div></div></footer>
</div>
  );
}
